PAGE = dict(
    slug='trend',
    title='Pane::trend',
    signature='Trace& Pane::trend(Series x, Series y)',
    intro='Adds a **line**: the points `(x[i], y[i])` joined in the order given. It is the basic trace of a plot of one quantity against another and the one every line chart of [`flash`](../../flash_api_reference) is built on.\n\n`x` and `y` are anything that converts to a `Series`. They must have the same length, or one of them a single value, which is repeated. Empty series are refused. The line is not sorted: put the points in the order they should be joined. Series with `NaN` are accepted and drawn as far as the other values go.\n\nThe pane needs to be planar ([`pane2`](../studio/pane2.md)); a volumetric pane takes [`path3`](path3.md) instead.',
    parameters='**x**, **y** (`Series`-convertible)\n    The coordinates of the points. Equal lengths, or one of length 1.',
    returns='`Trace&`\n    The new trace, for styling.',
    examples=[
        dict(id='basic', text='A line through five points. Points are joined in the order they are given.',
             code='auto fig = studio("trend_basic");\nauto& pane = fig.pane2("p");\nTrace& line = pane.trend(std::vector<double>{1, 2, 3, 4, 5}, std::vector<double>{2, 4, 3, 5, 6});\nstd::cout << "traces: " << pane.trace_count() << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='order', text='The order is the order of the data: `trend` does not sort by x. The same five points in a different order make a different path.',
             code='auto fig = studio("trend_order");\nfig.mosaic(1, 2);\nauto& sorted = fig.pane2("sorted by x");\nsorted.trend(std::vector<double>{1, 2, 3, 4, 5}, std::vector<double>{1, 3, 2, 5, 4});\nauto& shuffled = fig.pane2("as given");\nshuffled.trend(std::vector<double>{3, 1, 5, 2, 4}, std::vector<double>{2, 1, 4, 3, 5});\nfig.save_svg("figure.svg");'),
        dict(id='two', text='Several traces on one pane, each added by its own call, take the accent colours of the theme in turn.',
             code='auto fig = studio("trend_two");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4, 5}, std::vector<double>{2, 4, 3, 5, 6}).label("first");\npane.trend(std::vector<double>{1, 2, 3, 4, 5}, std::vector<double>{3, 5, 4, 6, 7}).label("second");\npane.legend(KeyPlace::NorthWest);\nstd::cout << "traces: " << pane.trace_count() << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='broadcast', text='A single value is repeated to the length of the other series, so a flat line is `trend(x, 3.0)` written as a one-element series.',
             code='auto fig = studio("trend_broadcast");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4, 5}, pluss::series::linspace(3.0, 3.0, 1, pluss::ScalarType::Float64));\npane.trend(std::vector<double>{1, 2, 3, 4, 5}, std::vector<double>{2, 4, 3, 5, 6});\nfig.save_svg("figure.svg");'),
        dict(id='types', text='Anything that converts to a `Series` is accepted: `std::vector` of any arithmetic type, an initializer list, or a `Series`. The three calls draw the same line.',
             code='auto build = [&](int how) {\n  auto fig = studio("trend_types");\n  auto& pane = fig.pane2("p");\n  if (how == 0) pane.trend(std::vector<double>{1, 2, 3}, std::vector<double>{2, 4, 3});\n  if (how == 1) pane.trend(std::vector<int>{1, 2, 3}, std::vector<float>{2, 4, 3});\n  if (how == 2) pane.trend(pluss::series::linspace(1.0, 3.0, 3, pluss::ScalarType::Float64), std::vector<double>{2, 4, 3});\n  return fig.to_svg();\n};\nstd::cout << "vector<int>/<float> == vector<double>: " << (build(1) == build(0)) << ", linspace Series == vector: " << (build(2) == build(0)) << "\\n";\nauto fig = studio("trend_types_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3}, std::vector<double>{2, 4, 3});\nfig.save_svg("figure.svg");'),
        dict(id='single', text="One point is a valid trace, with nothing to join: it adds a trace that draws no line, and the pane's range still comes from it.",
             code='auto fig = studio("trend_single");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{2.0}, std::vector<double>{3.0});\nstd::cout << "traces: " << pane.trace_count() << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='errors', text='Inputs that cannot be drawn are refused when the trace is added, and the message names the method and the problem. The pane keeps the traces it had.',
             code='auto report = [](const char* what, auto&& call) {\n  auto fig = studio("trend_errors");\n  auto& pane = fig.pane2("p");\n  try {\n    call(pane);\n    std::cout << what << ": accepted\\n";\n  } catch (const pluss::Error& e) {\n    std::cout << what << ": " << e.message() << "\\n";\n  }\n};\nreport("lengths differ", [](Pane& pane) { pane.trend(std::vector<double>{1, 2, 3}, std::vector<double>{1, 2}); });\nreport("empty", [](Pane& pane) { pane.trend(std::vector<double>{}, std::vector<double>{}); });\nauto fig = studio("trend_errors_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{0, 1}, std::vector<double>{0, 1});\nfig.save_svg("figure.svg");'),
        dict(id='wrong_pane', text='`trend` needs a planar pane. On a volumetric pane it throws at once, naming the kind it needs, and nothing is added.',
             code='auto fig = studio("trend_wrong_pane");\nauto& pane = fig.pane3("p");\ntry {\n  pane.trend(std::vector<double>{0, 1}, std::vector<double>{0, 1});\n} catch (const pluss::Error& e) {\n  std::cout << e.message() << "\\n";\n}\nstd::cout << "traces: " << pane.trace_count() << "\\n";\nfig.save_svg("figure.svg");'),
    ],
    notes='- Returns the new [`Trace&`](../trace/label.md); the reference stays valid for the life of the pane, and the style calls of the trace ([`label`](../trace/label.md), [`stroke`](../trace/stroke.md), [`width`](../trace/width.md), ...) chain off it.\n- The data is copied into the trace when it is added, so changing the vector afterwards does not change the figure.\n',
    see=['[`Pane::path3`](path3.md): the line in three dimensions.', '[`Pane::cloud`](cloud.md): the points without the line.', '[`Pane::ribbon`](ribbon.md): the region under a line.'],
)
